228			protected ProjectGenerationRequest createProjectGenerationRequest(OptionSet options) {
229				List<?> nonOptionArguments = new ArrayList<Object>(options.nonOptionArguments());
230				Assert.state(nonOptionArguments.size() <= 1, "Only the target location may be specified");
231				ProjectGenerationRequest request = new ProjectGenerationRequest();
232				request.setServiceUrl(options.valueOf(this.target));
233				applyConfiguredValue(options, this.bootVersion, request::setBootVersion);
234				applyConfiguredDependencies(options, request);
235				applyConfiguredValue(options, this.javaVersion, request::setJavaVersion);
236				applyConfiguredValue(options, this.packageName, request::setPackageName);
237				request.setBuild(options.valueOf(this.build));
238				request.setFormat(options.valueOf(this.format));
239				request.setDetectType(options.has(this.build) || options.has(this.format));
240				applyConfiguredValue(options, this.type, request::setType);
241				applyConfiguredValue(options, this.packaging, request::setPackaging);
242				applyConfiguredValue(options, this.language, request::setLanguage);
243				applyConfiguredValue(options, this.groupId, request::setGroupId);
244				applyConfiguredValue(options, this.artifactId, request::setArtifactId);
245				applyConfiguredValue(options, this.name, request::setName);
246				applyConfiguredValue(options, this.version, request::setVersion);
247				applyConfiguredValue(options, this.description, request::setDescription);
248				request.setExtract(options.has(this.extract));
249				if (nonOptionArguments.size() == 1) {
250					String output = (String) nonOptionArguments.get(0);
251					request.setOutput(output);
252				}
253				return request;
254			}
